// Stable identity for callers that omit the `workflows` prop. `workflows` is a
// dependency of the detection debounce effect below — a fresh `[]` literal as
// the default parameter value would get a new identity every render, which
// would restart the 150ms debounce on every render for such callers.
const EMPTY_WORKFLOWS: WorkflowEntry[] = [];
const EMPTY_PRESETS: LauncherPresetEntry[] = [];
const EMPTY_REMOTES: RemoteOption[] = [];

// Lazy-load the backlog chat-compose/intent-review subtree. The app shell renders
// <Omnibar> on every route (src/app/Providers.tsx), so a static import of either
// component here would put their shared dependency, BacklogItemForm.tsx — and
// through it react-markdown/remark-gfm — in the Initial JS chunk, even though these
// views only render once the user actually drafts a backlog item from the omnibar.
const backlogComposeLoading = () => (
  <div style={{ padding: "24px", textAlign: "center", color: "var(--text-secondary)" }}>
    Loading…
  </div>
);
const BacklogItemIntentReview = lazyComponent(
  () =>
    import("@/components/backlog/BacklogItemIntentReview").then((m) => ({
      default: m.BacklogItemIntentReview,
    })),
  { loading: backlogComposeLoading },
);
const BacklogComposeWidget = lazyComponent(
  () =>
    import("@/components/backlog/BacklogComposeWidget").then((m) => ({
      default: m.BacklogComposeWidget,
    })),
  { loading: backlogComposeLoading },
);

interface OmnibarProps {
  isOpen: boolean;
  onClose: () => void;
  onCreateSession: (data: OmnibarSessionData) => Promise<void>;
  onNavigateToSession: (sessionId: string) => void;
  onNavigateToSessionInNewPane?: (sessionId: string) => void;
  onRunWorkflow?: (slug: string, arg: string) => Promise<void>;
  initialMode?: "discovery" | "creation";
  initialInput?: string;
  initialTitle?: string;
  /** Available workflows for @slug autocomplete. */
  workflows?: WorkflowEntry[];
  /** Launcher presets, fetched once by OmnibarContext and shared with the PresetDetector
   * registration there — passed through so OmnibarPresetList renders the same data the
   * detector resolves against, rather than each maintaining its own independent fetch. */
  launcherPresets?: LauncherPresetEntry[];
  launcherPresetsLoading?: boolean;
  launcherPresetsLoadError?: string | null;
  /** Configured remotes for the "Remote host" selector (ADR-001: remote-as-orthogonal-flag).
   * TODO(Phase 6): OmnibarContext will source this from a `remotesSlice` populated by a
   * ListRemotes RPC — until then it's an optional prop that defaults to empty (no selector
   * rendered, today's local-only behavior unchanged). */
  // eslint-disable-next-line no-restricted-syntax -- pre-existing: OmnibarProps already exceeded 12 props
  remotes?: RemoteOption[];
}

// Consolidated form state
export interface OmnibarFormState {
  sessionName: string;
  branch: string;
  program: string;
  category: string;
  autoYes: boolean;
  useTitleAsBranch: boolean;
  sessionType:
    | "directory"
    | "new_worktree"
    | "existing_worktree"
    | "one_off"
    | "new_project";
  existingWorktree: string;
  workingDir: string;
  // New project mode fields
  parentDir: string;
  projectName: string;
  newProjectSessionType: "directory" | "new_worktree";
  // Opt-in: when the path doesn't exist yet, create the directory and
  // initialize a new git repository. Only applies to directory / new_worktree.
  createIfMissing: boolean;
  firstPrompt: string;
  // Parallel fan-out: run the same prompt across this many isolated worktree sessions (1 = off,
  // 2-5 = fan out; server caps at 5). Only meaningful for new_worktree sessions.
  fanoutCount: number;
  // Autonomous mode: an orthogonal flag that composes with sessionType (any type
  // except one_off) rather than a session type of its own — see OmnibarCreationPanel's
  // "Autonomous mode" checkbox.
  autonomousMode: boolean;
  // Auto-approve (yolo mode): injects a per-agent CLI flag that skips permission/approval
  // prompts entirely. Independent of autoYes — see OmnibarCreationPanel's checkbox comment.
  autoApprove: boolean;
  // extraArgs carries a selected launcher preset's argv[1:] verbatim (never whitespace-split)
  // through to the extra_args RPC field. Parallel to program, which carries argv[0].
  extraArgs: string[];
  // Remote target: an orthogonal flag that composes with whichever sessionType is selected
  // (any type) rather than a session type of its own — see ADR-001
  // (remote-as-orthogonal-flag) and OmnibarCreationPanel's "Remote host" selector. Names an
  // already-configured RemoteConfig by name; undefined means "run locally" (today's default).
  remoteName?: string;
}

const INITIAL_FORM_STATE: OmnibarFormState = {
  sessionName: "",
  branch: "",
  program: "",
  category: "",
  autoYes: false,
  useTitleAsBranch: true,
  sessionType: "new_worktree",
  existingWorktree: "",
  workingDir: "",
  // New project mode defaults
  parentDir: "",
  projectName: "",
  newProjectSessionType: "new_worktree",
  createIfMissing: false,
  firstPrompt: "",
  fanoutCount: 1,
  autonomousMode: false,
  autoApprove: false,
  extraArgs: [],
  // undefined = local (this machine) — see OmnibarFormState.remoteName's doc comment.
  remoteName: undefined,
};

// Consolidated UI state
interface OmnibarUIState {
  showAdvanced: boolean;
  dropdownIndex: number;
  dropdownDismissed: boolean;
  resultHighlightIndex: number;
  atSuggestIndex: number;
}

export interface OmnibarSessionData {
  title: string;
  path: string;
  branch?: string;
  program: string;
  category?: string;
  prompt?: string;
  autoYes: boolean;
  // GitHub-specific
  gitHubOwner?: string;
  gitHubRepo?: string;
  gitHubPRNumber?: number;
  // Session type and worktree
  sessionType?: "directory" | "new_worktree" | "existing_worktree" | "one_off";
  existingWorktree?: string;
  workingDir?: string;
  initialPrompt?: string;
  // New project mode: tells the context layer to use SESSION_TYPE_NEW_PROJECT
  isNewProject?: boolean;
  // Explicit opt-in to create the directory + git repo if `path` doesn't exist.
  createIfMissing?: boolean;
  // Autonomous mode: run without human permission prompts (LLM approves tool calls).
  autonomousMode?: boolean;
  // Auto-approve (yolo mode): injects a per-agent CLI flag that skips permission/approval
  // prompts entirely. Independent of autoYes.
  autoApprove?: boolean;
  // Permission mode passed to Claude Code (e.g. "auto" for autonomous sessions).
  permissionMode?: string;
  aliasName?: string;
  extraCliFlags?: string;
  extraArgs?: string[];
  // Names an already-configured remote (RemoteConfig.Name) to run this session on over SSH,
  // per ADR-001 (remote-as-orthogonal-flag). Undefined runs locally — see
  // OmnibarFormState.remoteName's doc comment.
  remoteName?: string;
  // Parallel fan-out: when >= 2, the context layer calls FanOutSession instead of CreateSession.
  fanoutCount?: number;
}

// Validates a project name: no path separators, null bytes, or leading/trailing spaces/dots.
function isValidProjectName(name: string): boolean {
  if (!name.trim()) return false;
  return !/[/\\<>:"|?*\x00]/.test(name) && !/^\.|\.$|^ | $/.test(name);
}

const RESULT_LISTBOX_ID = "omnibar-result-listbox";

function protoSessionTypeToFormString(
  st: SessionType,
): OmnibarFormState["sessionType"] {
  switch (st) {
    case SessionType.DIRECTORY:
      return "directory";
    case SessionType.NEW_WORKTREE:
      return "new_worktree";
    case SessionType.EXISTING_WORKTREE:
      return "existing_worktree";
    case SessionType.ONE_OFF:
      return "one_off";
    default:
      return "new_worktree";
  }
}

export function Omnibar({
  isOpen,
  onClose,
  onCreateSession,
  onNavigateToSession,
  onNavigateToSessionInNewPane,
  onRunWorkflow,
  initialMode,
  initialInput,
  initialTitle,
  workflows = EMPTY_WORKFLOWS,
  launcherPresets = EMPTY_PRESETS,
  launcherPresetsLoading = false,
  launcherPresetsLoadError = null,
  remotes = EMPTY_REMOTES,
}: OmnibarProps) {
  const router = useRouter();
  const { setTheme } = useTheme();
  const { createBacklogItemFromChat } = useBacklogService();
  const { trackItem } = useBacklogCreationNotifier();
  const { addNotification } = useNotificationCommands();
  const createBacklogItemInBackground = useCallback(
    async (text: string) => {
      let result: Awaited<ReturnType<typeof createBacklogItemFromChat>> = null;
      try {
        result = await createBacklogItemFromChat(text);
      } catch {
        // fall through to the failure notification
      }
      if (!result) {
        addNotification({
          sessionId: "",
          sessionName: "",
          title: "Failed to create backlog item",
          message: `Your text was not saved: ${text.length > 200 ? `${text.slice(0, 200)}…` : text}`,
          notificationType: "error",
        });
        return;
      }
      trackItem(result.item.id, result.item.title);
      addNotification({
        sessionId: "",
        sessionName: "",
        title: "Backlog item created — triage starting",
        message: result.item.title,
        notificationType: "info",
        onView: () => router.push(`/backlog?item=${result.item.id}`),
      });
    },
    [createBacklogItemFromChat, trackItem, addNotification, router]
  );

  // Input state
  const [input, setInput] = useState("");
  // Debounced copy of input — used for Fuse searches to avoid running O(n log n) work
  // on every keystroke. The visible input still uses the raw value for instant response.
  const [debouncedInput, setDebouncedInput] = useState("");
  const debounceFuseRef = useRef<NodeJS.Timeout | null>(null);
  useEffect(() => {
    if (debounceFuseRef.current) clearTimeout(debounceFuseRef.current);
    debounceFuseRef.current = setTimeout(() => setDebouncedInput(input), 150);
    return () => {
      if (debounceFuseRef.current) clearTimeout(debounceFuseRef.current);
    };
  }, [input]);
  const [detection, setDetection] = useState<DetectionResult | null>(null);

  // Consolidated form state
  const [formState, setFormState] =
    useState<OmnibarFormState>(INITIAL_FORM_STATE);
  const setFormField = useCallback(
    <K extends keyof OmnibarFormState>(key: K, value: OmnibarFormState[K]) =>
      setFormState((prev) => ({ ...prev, [key]: value })),
    [],
  );

  // Consolidated UI state
  const [uiState, setUIState] = useState<OmnibarUIState>({
    showAdvanced: false,
    dropdownIndex: -1,
    dropdownDismissed: false,
    resultHighlightIndex: -1,
    atSuggestIndex: -1,
  });
  const setUIField = useCallback(
    <K extends keyof OmnibarUIState>(key: K, value: OmnibarUIState[K]) =>
      setUIState((prev) => ({ ...prev, [key]: value })),
    [],
  );

  const [activeDropdown, setActiveDropdown] = useState<
    "alias" | "workflow" | "search" | null
  >(null);
  const [aliasSuggestIndex, setAliasSuggestIndex] = useState(-1);

  // Submission state
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  // Non-null while reviewing an LLM-parsed backlog item draft (the
  // "backlog: <message>" trigger) — holds the raw text passed to
  // BacklogItemIntentReview. Replaces the entire omnibar body with the
  // review UI until the user confirms or cancels; see the early return
  // near this component's bottom.
  const [backlogReviewText, setBacklogReviewText] = useState<string | null>(null);
  // Dedicated multi-line compose mode opened by the "Create backlog item" button;
  // seeded from the current input so typed text is never discarded.
  const [backlogComposeText, setBacklogComposeText] = useState<string | null>(null);
  // Synchronous double-submit guard: `isSubmitting` state only becomes visible to
  // handleSubmit's closure after React commits the re-render, which leaves a window
  // for a second rapid click (e.g. a fast double-click) to read the same stale
  // `isSubmitting === false` closure value. A ref is updated synchronously in the
  // same call stack as the first click, so a second click arriving before React
  // re-renders is still rejected.
  const isSubmittingRef = useRef(false);

  // Mode state machine
  const [modeState, dispatchMode] = useModeReducer();

  // Confirmation dialog state for Directory mode with non-existent path
  const [showPathConfirmation, setShowPathConfirmation] = useState(false);
  const [pendingSessionData, setPendingSessionData] =
    useState<OmnibarSessionData | null>(null);

  // Convenience aliases for existing code
  // Destructure only fields needed for validation/submission logic in Omnibar.tsx
  const {
    sessionName,
    program,
    category,
    autoYes,
    autoApprove,
    sessionType,
    branch,
    useTitleAsBranch,
    existingWorktree,
    workingDir,
    parentDir,
    projectName,
    newProjectSessionType,
    createIfMissing,
  } = formState;
  const { showAdvanced } = uiState;
  const {
    dropdownIndex,
    dropdownDismissed,
    resultHighlightIndex,
    atSuggestIndex,
  } = uiState;
  // Used in detection auto-fill effects
  const setSessionName = useCallback(
    (v: string) => setFormField("sessionName", v),
    [setFormField],
  );
  const setBranch = useCallback(
    (v: string) => setFormField("branch", v),
    [setFormField],
  );

  // Selected launcher preset (list click or typed preset:<id>), drives the resolution chip.
  // Deliberately separate from `detection` state — a list click never touches the text input,
  // so it can't be derived from detection.type the way alias-resolution-chip is.
  const [selectedPreset, setSelectedPreset] =
    useState<LauncherPresetEntry | null>(null);
  const handlePresetSelect = useCallback(
    (preset: LauncherPresetEntry) => {
      // Unconditional overwrite (no "only if empty" guard) — a discrete list click/typed
      // shorthand resolution is a one-shot action, not continuous re-detection on every
      // keystroke, so the thrashing concern that motivates the alias auto-fill guard doesn't
      // apply here (see plan.md Pattern Decisions).
      const [presetProgram, ...extraArgs] = preset.argv;
      setFormField("program", presetProgram);
      setFormField("extraArgs", extraArgs);
      if (preset.defaultPath) {
        setFormField("workingDir", preset.defaultPath);
      }
      setSelectedPreset(preset);
    },
    [setFormField],
  );
  const setDropdownIndex = useCallback(
    (updater: number | ((prev: number) => number)) => {
      setUIState((prev) => ({
        ...prev,
        dropdownIndex:
          typeof updater === "function" ? updater(prev.dropdownIndex) : updater,
      }));
    },
    [],
  );
  const setDropdownDismissed = useCallback(
    (v: boolean) => setUIField("dropdownDismissed", v),
    [setUIField],
  );
  const setResultHighlightIndex = useCallback(
    (updater: number | ((prev: number) => number)) => {
      setUIState((prev) => ({
        ...prev,
        resultHighlightIndex:
          typeof updater === "function"
            ? updater(prev.resultHighlightIndex)
            : updater,
      }));
    },
    [],
  );

  // Refs
  const inputRef = useRef<HTMLInputElement>(null);
  const debounceRef = useRef<NodeJS.Timeout | null>(null);
  const lastSuggestedNameRef = useRef<string>("");
  const prevDetectionTypeRef = useRef<string | null>(null);
  // Tracks the input value as of the last time the detection effect actually
  // ran its body, so a reset_to_discovery dispatch only fires when input truly
  // transitioned away from empty — not merely because aliases/workflows finished
  // an async refetch while input was already empty (see reset_to_discovery guard below).
  const prevDetectionInputRef = useRef<string>("");
  // Stable ref so handleKeyDown can always call the latest handleSubmit without
  // a circular declaration-order dependency (handleKeyDown is declared before handleSubmit).
  const handleSubmitRef = useRef<() => void>(() => {});
  // Holds the latest attached image paths from OmnibarCreationPanel without causing re-renders.
  const attachedImagePathsRef = useRef<string[]>([]);
  // Refs for form fields read inside the detection effect — avoids re-triggering
  // the effect (and resetting to discovery mode) when only form fields change.
  const sessionNameRef = useRef(sessionName);
  const branchRef = useRef(branch);
  const programRef = useRef(program);
  useEffect(() => {
    sessionNameRef.current = sessionName;
  }, [sessionName]);
  useEffect(() => {
    branchRef.current = branch;
  }, [branch]);
  useEffect(() => {
    programRef.current = program;
  }, [program]);
  const lastSuggestedProgramRef = useRef<string>("");

  // API base URL for pre-session image uploads — uses shared helper for SSR/dev consistency.
  const uploadBaseUrl = getApiBaseUrl();

  // Determine whether completions should be active.
  const isPathInput =
    detection?.type === InputType.LocalPath ||
    detection?.type === InputType.PathWithBranch;

  // `>shell <dir>` is still typing its directory argument when no `-- command`
  // has been typed yet — offer the same directory completions as a normal path input.
  const shellMetadata =
    detection?.type === InputType.SpawnShell
      ? (detection.metadata as
          { shellDir?: string; shellCommand?: string } | undefined)
      : undefined;
  const isShellDirInput = Boolean(shellMetadata && !shellMetadata.shellCommand);

  // Use the detected local path (strips branch suffix for PathWithBranch), or the
  // in-progress `>shell` directory argument.
  const completionPrefix = isPathInput
    ? (detection?.localPath ?? input)
    : isShellDirInput
      ? (shellMetadata?.shellDir ?? "")
      : "";

  const isPathCompletionActive =
    (isPathInput || isShellDirInput) && completionPrefix.length > 0;

  const {
    entries: completionEntries,
    baseDir: completionBaseDir,
    pathExists,
    isLoading: isCompletionLoading,
    error: completionError,
  } = usePathCompletions(completionPrefix, {
    enabled: isPathCompletionActive,
    directoriesOnly: true,
  });

  const {
    getMatching: getHistoryMatching,
    getAll: getAllHistory,
    save: saveHistory,
  } = usePathHistory();

  // Worktree suggestions for the "Use Existing Worktree" mode.
  // Prefer the pre-selected repo path from creation_with_repo mode; fall back to the
  // live-detected local path when the user typed a path directly in the input.
  const repoPathForWorktrees =
    modeState.type === "creation_with_repo" && modeState.path
      ? modeState.path
      : isPathInput
        ? (detection?.localPath ?? "")
        : "";
  const {
    worktrees,
    isLoading: isWorktreesLoading,
    error: worktreesError,
  } = useWorktreeSuggestions(repoPathForWorktrees, {
    enabled: sessionType === "existing_worktree" && !!repoPathForWorktrees,
  });

  // Destination path preview: github_url mode previews the exact clone destination for a
  // detected GitHub URL/PR/shorthand; new_worktree mode previews the deterministic prefix
  // of where the worktree will be created (the real path also gets a random suffix at
  // creation time — see PreviewWorktreePath's doc comment).
  const isGitHubUrlDetection =
    detection?.type === InputType.GitHubPR ||
    detection?.type === InputType.GitHubBranch ||
    detection?.type === InputType.GitHubRepo ||
    detection?.type === InputType.GitHubShorthand;

  const destinationPreviewParams = useMemo(() => {
    if (isGitHubUrlDetection && detection?.parsedValue) {
      return { mode: "github_url" as const, input: detection.parsedValue };
    }
    if (
      sessionType === "new_worktree" &&
      repoPathForWorktrees &&
      sessionName.trim()
    ) {
      return {
        mode: "new_worktree" as const,
        input: "",
        repoPath: repoPathForWorktrees,
        sessionName: useTitleAsBranch ? sessionName : branch || sessionName,
      };
    }
    return null;
  }, [
    isGitHubUrlDetection,
    detection?.parsedValue,
    sessionType,
    repoPathForWorktrees,
    sessionName,
    useTitleAsBranch,
    branch,
  ]);

  const {
    path: destinationPreviewPath,
    isExact: destinationPreviewIsExact,
    isLoading: isDestinationPreviewLoading,
  } = useDestinationPathPreview(destinationPreviewParams, {
    enabled: destinationPreviewParams !== null,
  });

  // Convert live OS entries to CompletionEntry for type-safe downstream use.
  const liveEntries = useMemo<CompletionEntry[]>(
    () =>
      completionEntries.map((e) => ({
        name: e.name,
        path: e.path,
        isDirectory: e.isDirectory,
      })),
    [completionEntries],
  );

  // History entries matching the current prefix.
  const historyMatches = useMemo<CompletionEntry[]>(
    () =>
      isPathInput
        ? getHistoryMatching(completionPrefix).map((h) => ({
            name: h.path,
            path: h.path,
            isDirectory: true,
            isHistory: true,
          }))
        : [],
    [isPathInput, completionPrefix, getHistoryMatching],
  );

  // Merged entries: history first, then live (deduped against history).
  const mergedEntries = useMemo<CompletionEntry[]>(() => {
    const liveDeduped = liveEntries.filter(
      (e) => !historyMatches.some((h) => h.path === e.path),
    );
    return [...historyMatches, ...liveDeduped];
  }, [historyMatches, liveEntries]);

  const historyCount = historyMatches.length;

  const isDropdownVisible =
    isPathCompletionActive && mergedEntries.length > 0 && !dropdownDismissed;

  // Discovery mode derived from modeState
  const isDiscoveryMode = modeState.type === "discovery";

  // @command autocomplete — active while user is typing "@slug" (no space yet)
  const {
    isAtCommand,
    suggestions: atSuggestions,
    complete: completeAtCommand,
  } = useAtCommandSuggestions(input, workflows);
  const isAtDropdownVisible = isDiscoveryMode && isAtCommand;

  const { aliases, error: aliasError, refetch: refetchAliases } = useAliases();

  // Re-fetch aliases each time the omnibar opens so newly created aliases appear immediately.
  const prevIsOpenRef = useRef(false);
  useEffect(() => {
    if (isOpen && !prevIsOpenRef.current) {
      refetchAliases();
    }
    prevIsOpenRef.current = isOpen;
  }, [isOpen, refetchAliases]);
  const {
    isAliasBrowse,
    isAliasCompletion,
    filteredAliases,
    complete: completeAlias,
  } = useAliasSuggestions(input, aliases);
  const isAliasPaletteVisible =
    isDiscoveryMode && (isAliasBrowse || isAliasCompletion);

  // Session search query uses the debounced input so Fuse only runs after typing pauses.
  const sessionSearchQuery = useMemo(() => {
    if (!debouncedInput.trim()) return "";
    if (detection?.type === InputType.SessionSearch) return debouncedInput;
    // Eagerly treat as session search if input doesn't look like a path or URL
    if (
      !debouncedInput.startsWith("/") &&
      !debouncedInput.startsWith("~") &&
      !debouncedInput.startsWith("http")
    ) {
      return debouncedInput;
    }
    return "";
  }, [debouncedInput, detection]);
  const sessionResults = useSessionSearch(sessionSearchQuery);

  const allRepoEntries = useMemo(() => getAllHistory(50), [getAllHistory]);
  const repoFuse = useMemo(
    () =>
      new Fuse(allRepoEntries, {
        keys: [{ name: "path", weight: 1.0 }],
        threshold: 0.4,
        ignoreLocation: true,
        minMatchCharLength: 1,
      }),
    [allRepoEntries],
  );

  const activeSortedSessions = useAppSelector(
    selectActiveSessionsSortedByUpdatedAt,
  );

  const displayedSessionResults = useMemo((): SessionSearchResult[] => {
    if (!debouncedInput.trim()) {
      return activeSortedSessions
        .slice(0, 5)
        .map((s) => ({ session: s, score: 0, matchedFields: [] }));
    }
    return sessionResults;
  }, [debouncedInput, sessionResults, activeSortedSessions]);

  const displayedRepoEntries = useMemo(() => {
    if (!debouncedInput.trim()) {
      return allRepoEntries.slice(0, 5);
    }
    return repoFuse
      .search(debouncedInput)
      .map((r) => r.item)
      .slice(0, 8);
  }, [debouncedInput, allRepoEntries, repoFuse]);

  const totalResultCount = getResultListItemCount(
    displayedSessionResults.length,
    displayedRepoEntries.length,
    true,
  );

  // Accept a completion entry: fill the input and continue for further completion.
  const handleCompletionSelect = useCallback(
    (entry: CompletionEntry) => {
      const newPath = entry.isDirectory ? entry.path + "/" : entry.path;
      const newInput = isShellDirInput ? `>shell ${newPath}` : newPath;
      setInput(newInput);
      setDropdownIndex(-1);
      setDropdownDismissed(false);
      inputRef.current?.focus();
    },
    [isShellDirInput, setDropdownIndex, setDropdownDismissed],
  );

  // Detect input type with debouncing
  useEffect(() => {
    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
    }

    debounceRef.current = setTimeout(() => {
      try {
        if (input.trim()) {
          // Pre-process slash commands before detection so /oneoff etc. aren't
          // misidentified as local paths by LocalPathDetector (priority 100).
          const slashCmd = parseSlashCommand(input);
          if (slashCmd) {
            setFormField("sessionType", slashCmd.sessionType);
          }
          const detectInput = slashCmd ? slashCmd.remainder : input;
          const result = detect(detectInput || input);
          setDetection(result);

          // Reset dropdown dismissed state when input type changes modes.
          // Prevents session results from being suppressed after user dismisses
          // path completion dropdown then backspaces to bare text.
          if (result.type !== prevDetectionTypeRef.current) {
            setDropdownDismissed(false);
          }
          prevDetectionTypeRef.current = result.type;

          // Update mode based on detection type
          if (result.type === InputType.NewSession) {
            // "new/" prefix typed → creation_with_repo mode with query from parsedValue
            dispatchMode({
              kind: "new_prefix_typed",
              query: result.parsedValue,
            });
          } else {
            dispatchMode({ kind: "detect", detection: result });
            if (result.type === InputType.SessionSearch) {
              setResultHighlightIndex(-1);
            }
          }

          // Auto-fill session name (and firstPrompt for `>` separator) if:
          // 1. Session name is empty, OR
          // 2. Session name matches the last auto-suggested name (not manually edited)
          // This allows suggestions to update as the user types the path (e.g., "~" → "sqlway")
          if (result.type === InputType.SessionSearch && !slashCmd) {
            // Derive-on-read: split on first `>` to populate name + firstPrompt
            const parsed = parseInputWithSeparator(input);
            const derivedName = parsed.name;
            if (
              derivedName &&
              (!sessionNameRef.current ||
                sessionNameRef.current === lastSuggestedNameRef.current)
            ) {
              setSessionName(derivedName);
              lastSuggestedNameRef.current = derivedName;
            }
            if (parsed.firstPrompt) {
              setFormField("firstPrompt", parsed.firstPrompt);
            }
          } else if (
            result.suggestedName &&
            result.type !== InputType.Alias &&
            result.type !== InputType.Command &&
            result.type !== InputType.SpawnShell
          ) {
            // Skip for Alias — the alias-specific block below handles name population
            // (running both would reset lastSuggestedNameRef mid-effect and cause oscillation).
            // Skip for Command/SpawnShell — their suggestedName is a human-readable label
            // ("Switch to Matrix theme"), not a session-name candidate.
            if (
              !sessionNameRef.current ||
              sessionNameRef.current === lastSuggestedNameRef.current
            ) {
              // Detectors like LocalPath/PathWithBranch/NewSession/GitHub* build suggestedName
              // from raw path segments, branch names, or free text — slug it here so every
              // detector gets a valid kebab-case name for free instead of each one remembering to.
              const slugged = toSessionSlug(result.suggestedName);
              setSessionName(slugged);
              lastSuggestedNameRef.current = slugged;
            }
          }

          // Auto-fill branch if detected
          if (result.branch && !branchRef.current) {
            setBranch(result.branch);
          }

          // When an alias resolves, populate form fields from its configured defaults
          // so the user can see (and optionally adjust) what will be created.
          if (result.type === InputType.Alias) {
            const aliasMeta = result.metadata as AliasMetadata | undefined;
            const alias = aliasMeta?.alias;
            if (alias) {
              if (
                alias.program &&
                (!programRef.current ||
                  programRef.current === lastSuggestedProgramRef.current)
              ) {
                setFormField("program", alias.program);
                lastSuggestedProgramRef.current = alias.program;
              }
              // UNSPECIFIED means "Default (directory)" in the alias editor — always apply it.
              // Skipping UNSPECIFIED left the form at its initial "new_worktree" default.
              const resolvedSessionType =
                alias.sessionType !== SessionType.UNSPECIFIED
                  ? protoSessionTypeToFormString(alias.sessionType)
                  : "directory";
              setFormField("sessionType", resolvedSessionType);
              setFormField("autoYes", alias.autoYes);
            }
            // Populate branch from @alias:branch syntax so the user can see/edit it.
            if (aliasMeta?.branch && !branchRef.current) {
              setBranch(aliasMeta.branch);
            }
            // If the user typed a label after the alias name (e.g. "@ssq my-feature"),
            // use it as the session name so they can see and edit it before submitting.
            // If the alias defines a name_prefix, prepend it (e.g. prefix "ssq-" → "ssq-my-feature").
            const typedLabel = aliasMeta?.label;
            const namePrefix = alias?.namePrefix ?? "";
            if (
              typedLabel &&
              (!sessionNameRef.current ||
                sessionNameRef.current === lastSuggestedNameRef.current)
            ) {
              // Slug the typed portion only — speech-to-text and free typing won't
              // produce dashes on their own (e.g. "deck drainage" → "deck-drainage").
              const suggested = namePrefix
                ? `${namePrefix}${toSessionSlug(typedLabel)}`
                : toSessionSlug(typedLabel);
              setSessionName(suggested);
              lastSuggestedNameRef.current = suggested;
            } else if (
              namePrefix &&
              (!sessionNameRef.current ||
                sessionNameRef.current === lastSuggestedNameRef.current)
            ) {
              // No label yet but prefix defined: show just the prefix so the user knows what to complete.
              setSessionName(namePrefix);
              lastSuggestedNameRef.current = namePrefix;
            }
          } else if (result.type === InputType.Preset) {
            // Typed preset:<id> shorthand resolves through the same handler as a list click,
            // so both entry points produce identical form-state effects (single code path).
            const presetMeta = result.metadata as PresetMetadata | undefined;
            if (presetMeta?.preset) {
              handlePresetSelect(presetMeta.preset);
            }
          }
        } else {
          // This branch also runs when aliases/workflows finish an async refetch
          // while input is (and already was) empty — that's an identity change in
          // this effect's dep array, not a real input edit. Only reset to discovery
          // when input actually transitioned from non-empty to empty, so it doesn't
          // stomp a mode the user reached another way (e.g. Ctrl+Shift+K creation
          // mode) before they've typed anything.
          if (prevDetectionInputRef.current.trim()) {
            setDetection(null);
            dispatchMode({ kind: "reset_to_discovery" });
            setResultHighlightIndex(-1);
          }
        }
        prevDetectionInputRef.current = input;
      } catch (err) {
        // Never let a thrown exception mid-update abandon UI state — leave the
        // last valid detection/canSubmit state in place and surface the failure.
        console.error("[Omnibar] input detection failed:", err);
        setError(
          err instanceof Error ? err.message : "Failed to process input",
        );
      }
    }, 150); // 150ms debounce

    return () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }
    };
    // aliases/workflows are included so detection re-evaluates once the async
    // alias/workflow lists resolve — otherwise a fast "@alias" typed before the
    // AliasDetector/WorkflowDetector registers permanently mis-detects (e.g. as
    // SessionSearch) with no keystroke left to trigger a re-run.
  }, [
    input,
    dispatchMode,
    setFormField,
    setBranch,
    setDropdownDismissed,
    setResultHighlightIndex,
    setSessionName,
    aliases,
    workflows,
    handlePresetSelect,
  ]);

  // Clear a stale submission error whenever the input value itself changes —
  // keyed on `input` alone (not the detection-debounce effect's deps, which
  // also include aliases/workflows) so an unrelated async refetch can't wipe
  // a just-shown error. Covers every setInput() call site (typing, recent
  // shell command chips, alias/at-command completion, clone session), not
  // just the <input>'s own onChange.
  useEffect(() => {
    setError(null);
  }, [input]);

  // Focus input when opened
  useEffect(() => {
    if (isOpen && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isOpen]);

  // Reset state when closed
  useEffect(() => {
    if (!isOpen) {
      setInput("");
      setDetection(null);
      setFormState(INITIAL_FORM_STATE);
      setUIState({
        showAdvanced: false,
        dropdownIndex: -1,
        dropdownDismissed: false,
        resultHighlightIndex: -1,
        atSuggestIndex: -1,
      });
      setError(null);
      setBacklogReviewText(null);
      setBacklogComposeText(null);
      // Defense-in-depth: handleSubmit's own finally blocks already reset this on
      // success/failure, but this instance never unmounts across open/close cycles, so
      // also clear it here in case onClose() didn't synchronously flip isOpen after a
      // submission (the original bug this guards against — see Omnibar.submitReset.test.tsx).
      setIsSubmitting(false);
      isSubmittingRef.current = false;
      lastSuggestedNameRef.current = "";
      prevDetectionTypeRef.current = null;
      dispatchMode({ kind: "reset_to_discovery" });
    }
  }, [isOpen, dispatchMode]);

  // Reset atSuggestIndex when leaving @ mode (user added space or cleared the @).
  useEffect(() => {
    if (!isAtCommand) {
      setUIField("atSuggestIndex", -1);
    }
  }, [isAtCommand, setUIField]);

  useEffect(() => {
    if (isAliasPaletteVisible) {
      setActiveDropdown("alias");
    } else if (isAtDropdownVisible) {
      setActiveDropdown("workflow");
    } else {
      setActiveDropdown(null);
    }
  }, [isAliasPaletteVisible, isAtDropdownVisible]);

  // On open: apply initialMode if provided
  useEffect(() => {
    if (isOpen && initialMode === "creation") {
      dispatchMode({ kind: "open_creation_direct" });
    }
  }, [isOpen, initialMode, dispatchMode]);

  // On open: pre-populate input if initialInput is provided
  useEffect(() => {
    if (isOpen && initialInput) {
      setInput(initialInput);
    }
  }, [isOpen, initialInput]);

  // On open: pre-populate sessionName if initialTitle is provided
  useEffect(() => {
    if (isOpen && initialTitle) {
      setSessionName(initialTitle);
    }
  }, [isOpen, initialTitle, setSessionName]);

  // Session result selection handlers
  const handleSessionSelect = useCallback(
    (session: Session) => {
      onNavigateToSession(session.id);
      onClose();
    },
    [onNavigateToSession, onClose],
  );

  const handleSessionSelectInNewPane = useCallback(
    (session: Session) => {
      onNavigateToSessionInNewPane?.(session.id);
      onClose();
    },
    [onNavigateToSessionInNewPane, onClose],
  );

  const handleCloneSession = useCallback(
    (session: Session) => {
      // Pre-fill the input with the source session's repo (not its worktree, which
      // is unique to that session) and switch to creation mode.
      if (session.repoRoot) {
        setInput(session.repoRoot);
        dispatchMode({ kind: "select_repo", path: session.repoRoot });
        setResultHighlightIndex(-1);
        setDropdownDismissed(false);
        inputRef.current?.focus();
      }
    },
    [dispatchMode, setDropdownDismissed, setResultHighlightIndex],
  );

  const handleRepoSelect = useCallback(
    (path: string) => {
      setInput(path + "/");
      dispatchMode({ kind: "select_repo", path });
      setResultHighlightIndex(-1);
      setDropdownDismissed(false);
      inputRef.current?.focus();
    },
    [dispatchMode, setDropdownDismissed, setResultHighlightIndex],
  );

  // Seeds compose mode from the typed input, minus a leading "backlog:" trigger,
  // so the prefix never ends up in the created item.
  const openBacklogCompose = useCallback(() => {
    setBacklogComposeText(input.trim().replace(/^backlog:\s*/i, ""));
    setResultHighlightIndex(-1);
  }, [input, setResultHighlightIndex]);

  const dispatchHighlightedResultAction = useCallback(
    (index: number) => {
      if (index < displayedSessionResults.length) {
        handleSessionSelect(displayedSessionResults[index].session);
      } else {
        const repoIndex = index - displayedSessionResults.length;
        if (repoIndex < displayedRepoEntries.length) {
          handleRepoSelect(displayedRepoEntries[repoIndex].path);
        } else if (repoIndex === displayedRepoEntries.length) {
          dispatchMode({ kind: "open_creation_direct" });
          setResultHighlightIndex(-1);
        } else {
          openBacklogCompose();
        }
      }
    },
    [
      displayedSessionResults,
      displayedRepoEntries,
      handleSessionSelect,
      handleRepoSelect,
      dispatchMode,
      setResultHighlightIndex,
      openBacklogCompose,
    ],
  );

  // Handle keyboard shortcuts
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      // Alias palette keyboard navigation
      if (activeDropdown === "alias" && filteredAliases.length > 0) {
        if (e.key === "ArrowDown") {
          e.preventDefault();
          setAliasSuggestIndex((i) =>
            Math.min(i + 1, filteredAliases.length - 1),
          );
          return;
        }
        if (e.key === "ArrowUp") {
          e.preventDefault();
          setAliasSuggestIndex((i) => Math.max(i - 1, -1));
          return;
        }
        if (e.key === "Tab" || e.key === "Enter") {
          e.preventDefault();
          // Default to the top suggestion when nothing has been arrow-key-highlighted,
          // matching Tab's fallback so a bare Enter accepts the best match.
          const idx = aliasSuggestIndex >= 0 ? aliasSuggestIndex : 0;
          if (filteredAliases[idx]) {
            setInput(completeAlias(filteredAliases[idx]));
            setAliasSuggestIndex(-1);
          }
          return;
        }
        if (e.key === "Escape") {
          e.preventDefault();
          if (input.length > 1) {
            setInput("@");
          } else {
            setInput("");
          }
          setAliasSuggestIndex(-1);
          return;
        }
      }

      // @command autocomplete (highest priority when visible)
      if (isAtDropdownVisible) {
        if (e.key === "ArrowDown") {
          e.preventDefault();
          setUIField(
            "atSuggestIndex",
            Math.min(atSuggestIndex + 1, atSuggestions.length - 1),
          );
          return;
        }
        if (e.key === "ArrowUp") {
          e.preventDefault();
          setUIField("atSuggestIndex", Math.max(atSuggestIndex - 1, -1));
          return;
        }
        if (e.key === "Tab" || e.key === "Enter") {
          // Default to the top suggestion when nothing has been arrow-key-highlighted,
          // matching Tab's existing fallback so a bare Enter accepts the best match.
          const idx = atSuggestIndex >= 0 ? atSuggestIndex : 0;
          if (atSuggestions[idx]) {
            e.preventDefault();
            setInput(completeAtCommand(atSuggestions[idx]));
            setUIField("atSuggestIndex", -1);
          }
          return;
        }
        if (e.key === "Escape") {
          e.nativeEvent.stopImmediatePropagation();
          setUIField("atSuggestIndex", -1);
          return;
        }
      }

      // Discovery mode navigation (before dropdown check)
      if (
        isDiscoveryMode &&
        (resultHighlightIndex >= 0 || e.key === "ArrowDown")
      ) {
        if (e.key === "ArrowDown") {
          e.preventDefault();
          setResultHighlightIndex((i) => Math.min(i + 1, totalResultCount - 1));
          return;
        }
        if (e.key === "ArrowUp") {
          e.preventDefault();
          setResultHighlightIndex((i) => Math.max(i - 1, -1));
          return;
        }
        if (e.key === "Enter" && !e.metaKey && resultHighlightIndex >= 0) {
          e.preventDefault();
          dispatchHighlightedResultAction(resultHighlightIndex);
          return;
        }
        if (e.key === "Escape" && resultHighlightIndex >= 0) {
          e.nativeEvent.stopImmediatePropagation();
          setResultHighlightIndex(-1);
          return;
        }
      }

      if (isDropdownVisible) {
        if (e.key === "ArrowDown") {
          e.preventDefault();
          setDropdownIndex((i) => Math.min(i + 1, mergedEntries.length - 1));
          return;
        }
        if (e.key === "ArrowUp") {
          e.preventDefault();
          setDropdownIndex((i) => Math.max(i - 1, -1));
          return;
        }
        if (e.key === "Tab") {
          e.preventDefault();
          if (dropdownIndex >= 0) {
            // Explicit selection (including history entries) → accept it.
            handleCompletionSelect(mergedEntries[dropdownIndex]);
          } else if (liveEntries.length === 1) {
            handleCompletionSelect(liveEntries[0]);
          } else if (liveEntries.length > 1) {
            // Extend input to longest common prefix of live entry names only.
            const lcp = liveEntries.reduce((acc, entry) => {
              let i = 0;
              while (
                i < acc.length &&
                i < entry.name.length &&
                acc[i] === entry.name[i]
              )
                i++;
              return acc.slice(0, i);
            }, liveEntries[0].name);
            if (lcp) {
              const sep = completionBaseDir.endsWith("/") ? "" : "/";
              const newPath = completionBaseDir + sep + lcp;
              setInput(isShellDirInput ? `>shell ${newPath}` : newPath);
              setDropdownDismissed(false);
            }
          }
          return;
        }
        if (e.key === "Enter" && !e.metaKey && dropdownIndex >= 0) {
          e.preventDefault();
          handleCompletionSelect(mergedEntries[dropdownIndex]);
          return;
        }
        if (e.key === "Escape") {
          // Stop the native event so the global document listener doesn't
          // also call onClose() — first Escape dismisses the dropdown only.
          e.nativeEvent.stopImmediatePropagation();
          setDropdownDismissed(true);
          setDropdownIndex(-1);
          return;
        }
      }

      // Tab cycles session type when in creation mode and no dropdown is open
      if (e.key === "Tab" && !isDiscoveryMode && !isDropdownVisible) {
        e.preventDefault();
        const types = SESSION_TYPES.map((t) => t.value);
        const idx = types.indexOf(sessionType as (typeof types)[number]);
        const next = types[(idx + 1) % types.length];
        setFormField("sessionType", next as OmnibarFormState["sessionType"]);
        return;
      }

      if (e.key === "Escape") {
        // Stop propagation so the global document listener doesn't call onClose() a second time.
        e.nativeEvent.stopImmediatePropagation();
        if (!isDiscoveryMode) {
          // Escape in creation mode: return to discovery rather than closing.
          // Second Escape (in discovery mode) will close.
          dispatchMode({ kind: "reset_to_discovery" });
          setInput("");
          setResultHighlightIndex(-1);
        } else {
          onClose();
        }
      } else if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
        // Cmd+Enter (Mac) / Ctrl+Enter (Linux/Windows) to submit.
        handleSubmitRef.current();
      } else if (e.key === "Enter") {
        // Plain Enter submits when the form is ready (creation mode), or fires a
        // fire-and-forget detection like @workflow invocation (discovery mode) —
        // reached here only when no result/dropdown entry consumed Enter above.
        // handleSubmit guards on canSubmit internally, so this is a no-op when the form is incomplete.
        handleSubmitRef.current();
      }
    },
    [
      isDiscoveryMode,
      resultHighlightIndex,
      totalResultCount,
      dispatchHighlightedResultAction,
      isDropdownVisible,
      mergedEntries,
      liveEntries,
      completionBaseDir,
      isShellDirInput,
      dropdownIndex,
      handleCompletionSelect,
      onClose,
      dispatchMode,
      sessionType,
      setFormField,
      setDropdownDismissed,
      setDropdownIndex,
      setResultHighlightIndex,
      isAtDropdownVisible,
      atSuggestIndex,
      atSuggestions,
      completeAtCommand,
      setUIField,
      activeDropdown,
      aliasSuggestIndex,
      filteredAliases,
      completeAlias,
      input,
    ],
  );

  // Leaving compose mode (cancel/Escape) remounts the input; put focus back on it.
  const wasComposingRef = useRef(false);
  useEffect(() => {
    const composing = backlogComposeText !== null;
    if (wasComposingRef.current && !composing && isOpen) inputRef.current?.focus();
    wasComposingRef.current = composing;
  }, [backlogComposeText, isOpen]);

  // Global keyboard handler
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      // Cmd+K or Ctrl+K to open (handled by parent)
      // Compose mode handles its own Escape (returns to the input, keeping the draft).
      if (isOpen && e.key === "Escape" && backlogComposeText === null) {
        onClose();
      }
    };

    document.addEventListener("keydown", handleGlobalKeyDown);
    return () => document.removeEventListener("keydown", handleGlobalKeyDown);
  }, [isOpen, onClose, backlogComposeText]);

  // Get type info for display
  const typeInfo = useMemo(() => {
    if (!detection) return INPUT_TYPE_INFO[InputType.Unknown];
    return INPUT_TYPE_INFO[detection.type];
  }, [detection]);

  // True only after path completion has resolved and the path is missing.
  // Also requires that we're working with a local path (GitHub URLs are
  // resolved server-side, so existence isn't meaningful here).
  const pathDoesNotExist =
    isPathInput && !isCompletionLoading && pathExists === false;

  // Check if we can submit
  const canSubmit = useMemo(() => {
    // One-off mode: only session name is required (no path needed).
    if (sessionType === "one_off") {
      return !!sessionName.trim();
    }

    // Autonomous mode composes with whichever sessionType is selected (checked below)
    // rather than replacing it — its only extra requirement is a goal, since that's
    // the orchestrator's sole signal of what to do.
    const autonomousNeedsGoal =
      formState.autonomousMode && !formState.firstPrompt?.trim();

    // New project mode: requires parentDir + projectName (valid), no path detection.
    if (sessionType === "new_project") {
      if (!sessionName.trim()) return false;
      if (!parentDir.trim()) return false;
      if (!projectName.trim()) return false;
      if (!isValidProjectName(projectName)) return false;
      if (
        newProjectSessionType === "new_worktree" &&
        !useTitleAsBranch &&
        !branch.trim()
      )
        return false;
      return !autonomousNeedsGoal;
    }

    // Recognized commands (>theme ..., >go ...) and spawn_shell are always submittable
    if (detection?.type === InputType.Command && detection.confidence === 1.0)
      return true;
    if (
      detection?.type === InputType.SpawnShell &&
      detection.confidence === 1.0
    )
      return true;
    // Chat backlog item creation (backlog: <message>) needs no sessionName/path.
    if (detection?.type === InputType.ChatBacklogItem) return true;
    // fanout N: <prompt> only prefills the variants count + first prompt; always submittable.
    if (detection?.type === InputType.FanOut) return true;
    // Workflow invocation (@slug [arg]) is fire-and-forget, no sessionName/path needed.
    if (
      detection?.type === InputType.Workflow &&
      detection.metadata?.workflowFound
    )
      return true;

    if (!input.trim()) return false;
    if (!sessionName.trim()) return false;
    if (
      !detection ||
      detection.type === InputType.Unknown ||
      detection.type === InputType.Command ||
      detection.type === InputType.SessionSearch ||
      detection.type === InputType.AliasNotFound ||
      detection.type === InputType.AliasBrowse
    )
      return false;
    if (detection.type === InputType.Alias) return true;

    // Validate session type specific requirements
    if (sessionType === "new_worktree") {
      // Branch is required unless using title as branch
      if (!useTitleAsBranch && !branch.trim()) return false;
    } else if (sessionType === "existing_worktree") {
      // Existing worktree path is required
      if (!existingWorktree.trim()) return false;
      // existing_worktree requires the parent repo path to actually exist
      if (pathDoesNotExist) return false;
    }

    // For directory / new_worktree: missing path requires explicit opt-in
    if (
      pathDoesNotExist &&
      (sessionType === "directory" || sessionType === "new_worktree") &&
      !createIfMissing
    ) {
      return false;
    }

    return !autonomousNeedsGoal;
  }, [
    input,
    sessionName,
    detection,
    sessionType,
    branch,
    useTitleAsBranch,
    existingWorktree,
    pathDoesNotExist,
    createIfMissing,
    parentDir,
    projectName,
    newProjectSessionType,
    formState.autonomousMode,
    formState.firstPrompt,
  ]);

  // Handle form submission
  const handleSubmit = useCallback(async () => {
    if (!canSubmit || isSubmitting || isSubmittingRef.current) return;
    isSubmittingRef.current = true;

    // Computed once and reused across every session-data branch below that carries a
    // selected preset's extraArgs through to the RPC.
    const extraArgsForSubmit =
      formState.extraArgs.length > 0 ? formState.extraArgs : undefined;

    // Execute omnibar commands (>theme ..., >go ...) immediately without entering
    // session-creation flow. These are fire-and-forget; no loading state needed.
    if (
      detection?.type === InputType.Command &&
      detection.confidence === 1.0 &&
      detection.metadata
    ) {
      const { commandType, commandArg } = detection.metadata as {
        commandType: string;
        commandArg: string;
      };
      if (commandType === "theme") {
        setTheme(commandArg as ThemeName);
      } else if (commandType === "navigate") {
        router.push(commandArg);
      }
      onClose();
      return;
    }

    // Chat backlog item creation (backlog: <message>) — opens the LLM-parsed
    // review UI instead of creating immediately; see backlogReviewText's
    // early-return render branch below. isSubmittingRef is cleared here (not
    // in a finally block) since control doesn't return to this function once
    // the review UI takes over.
    if (detection?.type === InputType.ChatBacklogItem) {
      isSubmittingRef.current = false;
      setBacklogComposeText(null);
      setBacklogReviewText(detection.parsedValue);
      return;
    }

    // fanout N: <prompt> — prefill the variants input and first prompt, then let the user
    // pick the repo path and submit through the normal creation flow.
    if (detection?.type === InputType.FanOut) {
      const count = Number(detection.metadata?.fanoutCount ?? 2);
      setFormField("fanoutCount", count);
      setFormField("firstPrompt", detection.parsedValue);
      setFormField("sessionType", "new_worktree");
      setInput("");
      isSubmittingRef.current = false;
      return;
    }

    // Spawn shell command (>shell [dir] [-- command]) — creates a real terminal session
    // via the standard session-creation flow, rooted at `shellDir` (if given) and running
    // `shellCommand` as the session program (defaults to an interactive shell).
    if (
      detection?.type === InputType.SpawnShell &&
      detection.confidence === 1.0
    ) {
      const { shellDir, shellCommand } = (detection.metadata ?? {}) as {
        shellDir?: string;
        shellCommand?: string;
      };
      const sessionData: OmnibarSessionData = {
        title: shellCommand
          ? shellCommand
          : shellDir
            ? `Terminal: ${shellDir}`
            : "Terminal",
        path: shellDir ?? "",
        program: shellCommand ?? "bash",
        sessionType: shellDir ? "directory" : "one_off",
        createIfMissing: Boolean(shellDir),
        autoYes: false,
        autoApprove: false,
      };
      setIsSubmitting(true);
      setError(null);
      try {
        await onCreateSession(sessionData);
        if (shellCommand) addRecentShellCommand(shellCommand);
        onClose();
      } catch (err) {
        setError(
          err instanceof Error ? err.message : "Failed to create session",
        );
      } finally {
        setIsSubmitting(false);
        isSubmittingRef.current = false;
      }
      return;
    }

    // Workflow invocation (@slug [arg]) — fire-and-forget, no session-creation flow.
    if (
      detection?.type === InputType.Workflow &&
      detection.metadata?.workflowFound
    ) {
      const { slug, workflowArg } = detection.metadata as {
        slug: string;
        workflowArg: string;
      };
      void onRunWorkflow?.(slug, workflowArg ?? "");
      onClose();
      return;
    }

    // Alias invocation (@aliasname [...]) — create session with alias context.
    if (detection?.type === InputType.Alias && detection.metadata?.aliasName) {
      const aliasMeta = detection.metadata as unknown as AliasMetadata;
      const { aliasName, branch: aliasBranch, label, extraFlags } = aliasMeta;
      const sessionTitle =
        sessionName.trim() || label?.trim() || String(aliasName);
      // Apply useTitleAsBranch for new_worktree alias sessions, same as the regular path.
      let aliasFinalBranch =
        branch.trim() || (aliasBranch !== undefined ? String(aliasBranch) : "");
      if (
        sessionType === "new_worktree" &&
        useTitleAsBranch &&
        !aliasFinalBranch
      ) {
        aliasFinalBranch = sessionTitle;
      }
      const firstPromptText = formState.firstPrompt?.trim() || undefined;
      const sessionData: OmnibarSessionData = {
        title: sessionTitle,
        path: "",
        program: program || "",
        autoYes,
        autoApprove,
        aliasName: String(aliasName),
        branch: aliasFinalBranch || undefined,
        extraCliFlags:
          extraFlags !== undefined ? String(extraFlags) : undefined,
        extraArgs: extraArgsForSubmit,
        sessionType: sessionType as
          "directory" | "new_worktree" | "existing_worktree" | "one_off",
        workingDir: workingDir.trim() || undefined,
        category: category.trim() || undefined,
        initialPrompt: firstPromptText,
      };
      setIsSubmitting(true);
      setError(null);
      try {
        await onCreateSession(sessionData);
        onClose();
      } catch (err) {
        setError(
          err instanceof Error ? err.message : "Failed to create session",
        );
      } finally {
        setIsSubmitting(false);
        isSubmittingRef.current = false;
      }
      return;
    }

    setIsSubmitting(true);
    setError(null);

    try {
      // Determine final branch name
      let finalBranch = branch.trim();
      if (
        (sessionType === "new_worktree" ||
          (sessionType === "new_project" &&
            newProjectSessionType === "new_worktree")) &&
        useTitleAsBranch
      ) {
        finalBranch = sessionName.trim();
      }

      // Build prompt from attached image paths (pre-session uploads go to temp dir).
      const imagePaths = attachedImagePathsRef.current;
      const finalPrompt =
        imagePaths.length > 0 ? imagePaths.join(" ") : undefined;
      const firstPromptText = formState.firstPrompt?.trim() || undefined;

      let sessionData: OmnibarSessionData;

      if (sessionType === "new_project") {
        // New project mode: build the resolved path from parentDir + projectName
        const resolvedPath = `${parentDir.trim().replace(/\/$/, "")}/${projectName.trim()}`;
        sessionData = {
          title: sessionName.trim(),
          path: resolvedPath,
          branch:
            newProjectSessionType === "new_worktree"
              ? finalBranch || undefined
              : undefined,
          program,
          category: category.trim() || undefined,
          prompt: finalPrompt,
          autoYes,
          autoApprove,
          sessionType: newProjectSessionType,
          isNewProject: true,
          initialPrompt: firstPromptText,
          extraArgs: extraArgsForSubmit,
        };
      } else {
        // Autonomous mode composes with sessionType (any type except one_off) rather
        // than replacing it — path/branch/worktree fields flow from the actual
        // selected type exactly as they would for a non-autonomous session.
        const isAutonomous = formState.autonomousMode;
        const isOneOff = sessionType === "one_off";
        sessionData = {
          title: sessionName.trim(),
          path: isOneOff ? "" : detection?.localPath || "",
          branch: isOneOff ? undefined : finalBranch || undefined,
          program,
          category: category.trim() || undefined,
          prompt: finalPrompt,
          autoYes,
          autoApprove,
          sessionType,
          existingWorktree: isOneOff
            ? undefined
            : existingWorktree.trim() || undefined,
          workingDir: isOneOff ? undefined : workingDir.trim() || undefined,
          autonomousMode: isAutonomous ? true : undefined,
          permissionMode: isAutonomous ? "auto" : undefined,
          // Remote target composes with sessionType exactly like autonomousMode above —
          // passed through only when set (ADR-001: remote-as-orthogonal-flag).
          remoteName: formState.remoteName || undefined,
          // Only forward when relevant (non-existent path + opt-in checked).
          createIfMissing:
            pathDoesNotExist && createIfMissing ? true : undefined,
          initialPrompt: firstPromptText,
          extraArgs: extraArgsForSubmit,
          fanoutCount:
            sessionType === "new_worktree" && formState.fanoutCount >= 2
              ? formState.fanoutCount
              : undefined,
        };

        // Handle GitHub URLs - path will be resolved server-side
        if (!isOneOff && detection?.gitHubRef) {
          sessionData.gitHubOwner = detection.gitHubRef.owner;
          sessionData.gitHubRepo = detection.gitHubRef.repo;
          sessionData.gitHubPRNumber = detection.gitHubRef.prNumber;

          // For GitHub URLs, set path to the parsed value for server-side cloning
          if (!sessionData.path) {
            sessionData.path = detection.parsedValue;
          }
        }
      }

      try {
        await onCreateSession(sessionData);
      } catch (err) {
        // R2: Directory mode with non-existent path → show confirmation dialog
        if (
          sessionType === "directory" &&
          err instanceof Error &&
          (err.message.includes("not found") ||
            err.message.includes("CodeNotFound") ||
            err.message.includes("path does not exist"))
        ) {
          setPendingSessionData(sessionData);
          setShowPathConfirmation(true);
          setIsSubmitting(false);
          isSubmittingRef.current = false;
          return;
        }
        throw err;
      }

      // Persist the chosen path to history for future completions.
      if (isPathInput && detection?.localPath && sessionType !== "one_off") {
        saveHistory(detection.localPath);
      }
      onClose();
    } catch (err) {
      const message =
        err instanceof Error ? err.message : "Failed to create session";
      setError(message);
    } finally {
      setIsSubmitting(false);
      isSubmittingRef.current = false;
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- pre-existing; adding formState.fanoutCount/setFormField would change re-render/callback-identity behavior, unverified here
  }, [
    canSubmit,
    isSubmitting,
    branch,
    sessionName,
    sessionType,
    useTitleAsBranch,
    detection,
    program,
    category,
    autoYes,
    autoApprove,
    existingWorktree,
    workingDir,
    parentDir,
    projectName,
    newProjectSessionType,
    pathDoesNotExist,
    createIfMissing,
    isPathInput,
    saveHistory,
    onCreateSession,
    onClose,
    onRunWorkflow,
    formState.firstPrompt,
    formState.autonomousMode,
    formState.extraArgs,
    formState.remoteName,
    router,
    setTheme,
  ]);

  // Keep the ref in sync so handleKeyDown always dispatches the latest version.
  useEffect(() => {
    handleSubmitRef.current = handleSubmit;
  }, [handleSubmit]);

  if (!isOpen) return null;

  // Reviewing an LLM-parsed backlog item draft (backlog: <message>) replaces
  // the entire omnibar body — a different UI mode from session creation, not
  // another branch of the input/results form below.
  if (backlogReviewText !== null) {
    return (
      <div
        className={overlay}
        onClick={onClose}
        role="dialog"
        aria-modal="true"
        aria-labelledby="omnibar-title"
        data-testid="omnibar"
      >
        <div className={modal} data-testid="omnibar-modal" onClick={(e) => e.stopPropagation()}>
          <BacklogItemIntentReview
            initialText={backlogReviewText}
            onDone={(item: BacklogItem) => {
              setBacklogReviewText(null);
              onClose();
              router.push(`/backlog?item=${item.id}`);
            }}
            onCancel={() => setBacklogReviewText(null)}
          />
        </div>
      </div>
    );
  }

  // Compose mode: dedicated textarea; Create closes the omnibar and creates the
  // item in the background, with triage progress reported via notifications.
  if (backlogComposeText !== null) {
    return (
      <div
        className={overlay}
        // Backdrop clicks are ignored: the draft lives in the widget and only Cancel/Escape preserve it.
        role="dialog"
        aria-modal="true"
        aria-labelledby="backlog-compose-title"
        data-testid="omnibar"
      >
        <div className={modal} data-testid="omnibar-modal" onClick={(e) => e.stopPropagation()}>
          <BacklogComposeWidget
            initialText={backlogComposeText}
            onSubmit={(text) => {
              setBacklogComposeText(null);
              onClose();
              void createBacklogItemInBackground(text);
            }}
            onCancel={(draft) => {
              setInput(draft);
              setBacklogComposeText(null);
            }}
          />
        </div>
      </div>
    );
  }

  const isMac = (() => {
    try {
      return (
        typeof navigator !== "undefined" &&
        /Mac|iPhone|iPad|iPod/.test(navigator.platform)
      );
    } catch {
      return false;
    }
  })();

  return (
    <div
      className={overlay}
      onClick={onClose}
      role="dialog"
      aria-modal="true"
      aria-labelledby="omnibar-title"
      data-testid="omnibar"
    >
      <div
        className={modal}
        data-testid="omnibar-modal"
        onClick={(e) => e.stopPropagation()}
        onKeyDown={handleKeyDown}
      >
        {/* Main Input */}
        <div className={inputContainer}>
          <span className={typeIndicator} aria-hidden="true">
            {sessionType === "one_off"
              ? "⚡"
              : formState.autonomousMode
                ? "🤖"
                : typeInfo.icon}
          </span>
          <input
            ref={inputRef}
            type="text"
            className={inputClass}
            placeholder={
              sessionType === "one_off"
                ? "Session title is the only thing needed…"
                : formState.autonomousMode
                  ? "Session title (agent will run without human approval)…"
                  : isDiscoveryMode
                    ? "Jump to session, @alias, or search repos..."
                    : "Enter path, GitHub URL, or owner/repo..."
            }
            value={input}
            onChange={(e) => {
              setInput(e.target.value);
              setDropdownDismissed(false);
              setDropdownIndex(-1);
            }}
            autoComplete="off"
            autoCorrect="off"
            autoCapitalize="off"
            spellCheck={false}
            role="combobox"
            aria-label="Session source input"
            aria-autocomplete="list"
            aria-expanded={
              isDiscoveryMode
                ? displayedSessionResults.length > 0 ||
                  displayedRepoEntries.length > 0
                : isDropdownVisible
            }
            aria-controls={
              isDiscoveryMode ? RESULT_LISTBOX_ID : "path-completion-listbox"
            }
            aria-activedescendant={
              isDiscoveryMode
                ? getHighlightedItemId(
                    RESULT_LISTBOX_ID,
                    displayedSessionResults,
                    displayedRepoEntries,
                    resultHighlightIndex,
                  )
                : isDropdownVisible && dropdownIndex >= 0
                  ? `path-completion-listbox-option-${dropdownIndex}`
                  : undefined
            }
          />
          {/* Path existence indicator. When the path is missing and the user
              has opted in to create it, swap ✗ for + so the affordance reads
              as "create" rather than "broken". */}
          {isPathInput && !isDiscoveryMode && input.trim() && (
            <span
              className={pathIndicator}
              aria-live="polite"
              aria-label={
                isCompletionLoading
                  ? "Checking path"
                  : pathExists
                    ? "Path exists"
                    : createIfMissing
                      ? "New repository will be created"
                      : "Path does not exist"
              }
            >
              {isCompletionLoading ? (
                <span className={pathIndicatorLoading} aria-hidden="true">
                  ⟳
                </span>
              ) : pathExists ? (
                <span className={pathIndicatorValid} aria-hidden="true">
                  ✓
                </span>
              ) : createIfMissing ? (
                <span className={pathIndicatorValid} aria-hidden="true">
                  +
                </span>
              ) : (
                <span className={pathIndicatorInvalid} aria-hidden="true">
                  ✗
                </span>
              )}
            </span>
          )}
        </div>

        {isAliasPaletteVisible && (
          <AliasPalette
            aliases={filteredAliases}
            input={input}
            selectedIndex={aliasSuggestIndex}
            onSelect={(alias) => {
              setInput(completeAlias(alias));
              setAliasSuggestIndex(-1);
            }}
            error={aliasError}
          />
        )}

        {/* @command autocomplete — shown in discovery mode while typing @slug */}
        {isAtDropdownVisible && (
          <AtCommandDropdown
            id="at-command-listbox"
            suggestions={atSuggestions}
            selectedIndex={atSuggestIndex}
            onSelect={(wf) => {
              setInput(completeAtCommand(wf));
              setUIField("atSuggestIndex", -1);
              inputRef.current?.focus();
            }}
          />
        )}

        {detection?.type === InputType.Alias &&
          detection.metadata &&
          (() => {
            const m = detection.metadata as Record<string, unknown>;
            return (
              <div
                role="status"
                aria-live="polite"
                data-testid="alias-resolution-chip"
              >
                <span>Alias resolved: @{String(m.aliasName)}</span>
                {m.branch ? <span> :{String(m.branch)}</span> : null}
                {m.label ? <span> · {String(m.label)}</span> : null}
                {m.extraFlags ? (
                  <span> · {String(m.extraFlags)} (appended)</span>
                ) : null}
              </div>
            );
          })()}
        {detection?.type === InputType.Workflow &&
          !!detection.metadata?.workflowFound &&
          (() => {
            const { workflow, workflowArg } = detection.metadata as {
              workflow?: WorkflowEntry;
              workflowArg?: string;
            };
            return (
              <div
                role="status"
                aria-live="polite"
                data-testid="workflow-resolution-chip"
              >
                <span>
                  Workflow: @{workflow?.slug}
                  {workflow?.name ? ` (${workflow.name})` : ""}
                </span>
                {workflow?.description ? (
                  <span> · {workflow.description}</span>
                ) : null}
                <span> · arg: {workflowArg ? workflowArg : "(none)"}</span>
              </div>
            );
          })()}
        {detection?.type === InputType.AliasNotFound &&
          (() => {
            const m = detection.metadata as Record<string, unknown> | undefined;
            return (
              <div
                role="alert"
                aria-live="assertive"
                data-testid="alias-not-found"
              >
                No alias &apos;@{String(m?.slug)}&apos;
              </div>
            );
          })()}
        {selectedPreset && (
          <div
            role="status"
            aria-live="polite"
            data-testid="preset-resolution-chip"
          >
            Preset applied: {selectedPreset.label} ({program}
            {formState.extraArgs.length > 0
              ? ` ${formState.extraArgs.join(" ")}`
              : ""}
            )
          </div>
        )}
        {detection?.type === InputType.PresetNotFound &&
          (() => {
            const m = detection.metadata as PresetNotFoundMetadata | undefined;
            return (
              <div
                role="alert"
                aria-live="assertive"
                data-testid="preset-not-found"
              >
                No preset &apos;{m?.typedId}&apos;
              </div>
            );
          })()}
        {detection?.type === InputType.SpawnShell &&
          (() => {
            const { shellDir, shellCommand } = (detection.metadata ?? {}) as {
              shellDir?: string;
              shellCommand?: string;
            };
            const recentCommands = getRecentShellCommands();
            return (
              <>
                <div
                  role="status"
                  aria-live="polite"
                  data-testid="spawn-shell-chip"
                >
                  <span>
                    {shellCommand ? `Run "${shellCommand}"` : "Open terminal"}
                  </span>
                  {shellDir ? <span> in {shellDir}</span> : null}
                </div>
                {error && (
                  <div
                    className={errorClass}
                    role="alert"
                    aria-live="assertive"
                    data-testid="spawn-shell-error"
                  >
                    {error}
                  </div>
                )}
                {!shellCommand && !shellDir && recentCommands.length > 0 && (
                  <div data-testid="spawn-shell-recent-commands">
                    {recentCommands.map((cmd) => (
                      <button
                        key={cmd}
                        type="button"
                        data-testid="spawn-shell-recent-command"
                        // eslint-disable-next-line analytics/require-on-click -- pre-existing, unrelated
                        onClick={() => {
                          setInput(`>shell -- ${cmd}`);
                          inputRef.current?.focus();
                        }}
                      >
                        {cmd}
                      </button>
                    ))}
                  </div>
                )}
              </>
            );
          })()}
        {isShellDirInput && isDropdownVisible && (
          <PathCompletionDropdown
            id="shell-dir-completion-listbox"
            entries={mergedEntries}
            historyCount={historyCount}
            selectedIndex={dropdownIndex}
            onSelect={handleCompletionSelect}
            isLoading={isCompletionLoading}
          />
        )}

        {/* Discovery mode: session results + recent repos */}
        {isDiscoveryMode && !isAtDropdownVisible && (
          <OmnibarResultList
            id={RESULT_LISTBOX_ID}
            sessionResults={displayedSessionResults}
            repoEntries={displayedRepoEntries}
            highlightedIndex={resultHighlightIndex}
            onSessionSelect={handleSessionSelect}
            onSessionOpenInNewPane={
              onNavigateToSessionInNewPane
                ? handleSessionSelectInNewPane
                : undefined
            }
            onRepoSelect={handleRepoSelect}
            onCloneSession={handleCloneSession}
            onCreateNew={() => {
              dispatchMode({ kind: "open_creation_direct" });
              setResultHighlightIndex(-1);
            }}
            onCreateBacklog={openBacklogCompose}
          />
        )}

        {/* Creation mode: path completion dropdown (existing, unchanged) */}
        {!isDiscoveryMode && isDropdownVisible && sessionType !== "one_off" && (
          <PathCompletionDropdown
            id="path-completion-listbox"
            entries={mergedEntries}
            historyCount={historyCount}
            selectedIndex={dropdownIndex}
            onSelect={handleCompletionSelect}
            isLoading={isCompletionLoading}
          />
        )}

        {/* Path completion error */}
        {isPathInput && completionError && (
          <div className={completionErrorClass} aria-live="polite">
            Could not load completions
          </div>
        )}

        {/* Detection Badge */}
        {input.trim() && !isDiscoveryMode && sessionType !== "one_off" && (
          <div className={detectionInfo}>
            <span
              className={`${detectionBadge} ${
                detection?.type === InputType.Unknown ? unknown : ""
              }`}
            >
              {typeInfo.icon} {typeInfo.label}
            </span>
          </div>
        )}

        {/* Creation form + footer — delegated to OmnibarCreationPanel */}
        {!isDiscoveryMode && (
          <OmnibarCreationPanel
            formState={formState}
            setFormField={setFormField}
            onSubmit={handleSubmit}
            onCancel={onClose}
            onCreateBacklog={openBacklogCompose}
            worktrees={worktrees}
            isWorktreesLoading={isWorktreesLoading}
            worktreesError={worktreesError}
            isSubmitting={isSubmitting}
            canSubmit={canSubmit}
            error={error}
            showAdvanced={showAdvanced}
            onToggleAdvanced={() =>
              setUIField("showAdvanced", !uiState.showAdvanced)
            }
            path={
              modeState.type === "creation_with_repo"
                ? modeState.path
                : detection?.type === InputType.Alias
                  ? (detection.metadata as AliasMetadata | undefined)?.alias
                      ?.path || undefined
                  : undefined
            }
            uploadBaseUrl={uploadBaseUrl}
            onAttachedImagesChange={(paths) => {
              attachedImagePathsRef.current = paths;
            }}
            pathDoesNotExist={pathDoesNotExist}
            destinationPreviewPath={destinationPreviewPath}
            destinationPreviewIsExact={destinationPreviewIsExact}
            isDestinationPreviewLoading={isDestinationPreviewLoading}
            namePrefix={
              detection?.type === InputType.Alias
                ? ((detection.metadata as AliasMetadata | undefined)?.alias
                    ?.namePrefix ?? "")
                : ""
            }
            onPresetSelect={handlePresetSelect}
            launcherPresets={launcherPresets}
            launcherPresetsLoading={launcherPresetsLoading}
            launcherPresetsLoadError={launcherPresetsLoadError}
            remotes={remotes}
          />
        )}

        {/* R2: Confirmation dialog for Directory mode with non-existent path */}
        {showPathConfirmation && pendingSessionData && (
          <PathConfirmDialog
            path={pendingSessionData.path}
            onCancel={() => {
              setShowPathConfirmation(false);
              setPendingSessionData(null);
            }}
            onConfirm={async () => {
              setShowPathConfirmation(false);
              const retryData = {
                ...pendingSessionData,
                createIfMissing: true,
              };
              setPendingSessionData(null);
              setIsSubmitting(true);
              setError(null);
              try {
                await onCreateSession(retryData);
                onClose();
              } catch (err) {
                const message =
                  err instanceof Error ? err.message : "Failed to create session";
                setError(message);
              } finally {
                setIsSubmitting(false);
                isSubmittingRef.current = false;
              }
            }}
          />
        )}

        {/* Keyboard Shortcuts */}
        <div className={shortcuts}>
          <OmnibarModeBadge
            mode={isDiscoveryMode ? "discovery" : "creation"}
            onToggle={() =>
              isDiscoveryMode
                ? dispatchMode({ kind: "open_creation_direct" })
                : dispatchMode({ kind: "reset_to_discovery" })
            }
          />
          <span className={shortcut}>
            <span className={shortcutKey}>Esc</span> Close
          </span>
          {!isDiscoveryMode && (
            <button
              type="button"
              className={createButton}
              // eslint-disable-next-line analytics/require-on-click -- pre-existing, unrelated
              onClick={handleSubmit}
              disabled={!canSubmit || isSubmitting}
            >
              {isSubmitting ? "Creating…" : "Create Session"}
            </button>
          )}
          {isDiscoveryMode && (
            <>
              <span className={shortcut}>
                <span className={shortcutKey}>↑↓</span> Navigate
              </span>
              <span className={shortcut}>
                <span className={shortcutKey}>↵</span> Jump
              </span>
              <OmnibarBacklogButton
                onClick={openBacklogCompose}
                className={`${buttonClass} ${buttonSecondary} ${shortcutsBacklogButton}`}
              />
            </>
          )}
          {!isDiscoveryMode && isDropdownVisible && (
            <>
              <span className={shortcut}>
                <span className={shortcutKey}>↑↓</span> Navigate
              </span>
              <span className={shortcut}>
                <span className={shortcutKey}>Tab</span> Complete
              </span>
            </>
          )}
          {!isDiscoveryMode && !isDropdownVisible && (
            <span className={shortcut}>
              <span className={shortcutKey}>Tab</span> Cycle type
            </span>
          )}
        </div>
      </div>
    </div>
  );
}
